requestAccounts.example:
try {
  const accounts = await provider.requestAccounts();
  render(accounts[0]);
} catch {
  render('Connection declined. Nothing was shared.');
}

verifyMessageOfBIP322Simple.example:
const ok = await provider.verifyMessageOfBIP322Simple({
  address,
  message,
  signature,
});

getCapabilities.example:
const capabilities = await provider.getCapabilities();
if (!capabilities.anyProtocolSupported) {
  renderUnavailableState();
}

sendBitcoin.example:
try {
  const txid = await provider.sendBitcoin(toAddress, satoshis, { feeRate });
} catch (error) {
  // Protocol operation is not authorized: bitcoin.send in this build.
  renderUnavailableState();
}

